/**
 * Phase Orchestrator - Phase 4
 *
 * Manages execution of simulation phases in correct order.
 * Each phase is a self-contained unit of work that can be tested independently.
 */

import { GameState, GameEvent } from '@/types/game';
import { logger } from '../utils/asyncLogger';

/**
 * Random number generator function
 */
export type RNGFunction = () => number;

/**
 * Result of executing a phase
 */
export interface PhaseResult {
  /**
   * Events generated by this phase
   */
  events: GameEvent[];

  /**
   * Optional state replacement (for phases that return new state)
   */
  newState?: GameState;

  /**
   * Optional metadata about phase execution
   */
  metadata?: Record<string, any>;
}

/**
 * Represents a single simulation phase
 */
export interface SimulationPhase {
  /**
   * Unique identifier for this phase
   */
  readonly id: string;

  /**
   * Human-readable name for debugging
   */
  readonly name: string;

  /**
   * Execution order (lower numbers run first)
   * Use decimals for fine-grained ordering (e.g., 0.5, 1.0, 1.5)
   */
  readonly order: number;

  /**
   * Optional array of phase IDs that must execute BEFORE this phase
   *
   * Runtime validation ensures:
   * 1. Dependency phases have already executed this step
   * 2. Dependency phases have lower order numbers
   *
   * @example
   * // Any phase that modifies population AFTER mortality must declare dependency
   * readonly dependencies = ['bayesian_mortality_resolution'];
   *
   * // Phases can have multiple dependencies
   * readonly dependencies = ['climate_update', 'food_security_update'];
   */
  readonly dependencies?: readonly string[];

  /**
   * Execute this phase
   *
   * @param state - Current game state (may be mutated)
   * @param rng - Random number generator function
   * @param context - Optional context from previous phases
   * @returns Phase result with events and optional new state
   */
  execute(state: GameState, rng: RNGFunction, context?: PhaseContext): PhaseResult;
}

/**
 * Alias for backward compatibility
 */
export type Phase = SimulationPhase;

/**
 * Context shared between phases during a single step
 */
export interface PhaseContext {
  /**
   * Current month being simulated
   */
  month: number;

  /**
   * Logger instance (if available)
   */
  logger?: any;

  /**
   * Arbitrary data that phases can use to communicate
   */
  data: Map<string, any>;

  /**
   * Set of phase IDs that have executed in this step
   * Used for dependency validation
   */
  executedPhases: Set<string>;
}

/**
 * Orchestrates simulation phases in correct order
 */
export class PhaseOrchestrator {
  private phases: SimulationPhase[] = [];
  private sorted: boolean = false;

  // PERFORMANCE INSTRUMENTATION (Oct 28, 2025)
  private phaseTimings: Map<string, { totalMs: number; callCount: number }> = new Map();
  private enableTiming: boolean = false;

  /**
   * Register a phase
   */
  registerPhase(phase: SimulationPhase): void {
    this.phases.push(phase);
    this.sorted = false; // Mark as needing re-sort
  }

  /**
   * Register multiple phases at once
   */
  registerPhases(phases: SimulationPhase[]): void {
    this.phases.push(...phases);
    this.sorted = false;
  }

  /**
   * Execute all phases in order
   *
   * @param state - Game state (will be mutated)
   * @param rng - Random number generator
   * @param context - Optional context (created if not provided)
   * @returns All events generated by phases
   */
  executeAll(state: GameState, rng: RNGFunction, context?: PhaseContext): GameEvent[] {
    // Update logger with current simulation month (for yearly batching)
    logger.setSimulationMonth(state.currentMonth);

    // Ensure phases are sorted by order
    if (!this.sorted) {
      this.sortPhases();
    }

    // Create context if not provided
    const ctx: PhaseContext = context || {
      month: state.currentMonth,
      data: new Map(),
      executedPhases: new Set()
    };

    const allEvents: GameEvent[] = [];

    for (const phase of this.phases) {
      try {
        // PHASE DEPENDENCY VALIDATION (Oct 28, 2025)
        // Prevent race conditions like BayesianMortality → CountryPopulation bug
        if (phase.dependencies && phase.dependencies.length > 0) {
          for (const depId of phase.dependencies) {
            if (!ctx.executedPhases.has(depId)) {
              // Find the dependency phase to get its order number
              const depPhase = this.phases.find(p => p.id === depId);
              const depOrder = depPhase ? depPhase.order : 'unknown';

              throw new Error(
                `❌ PHASE DEPENDENCY VIOLATION: ${phase.name} (${phase.id})\n` +
                `   Requires phase: ${depId} (order: ${depOrder})\n` +
                `   Current phase order: ${phase.order}\n` +
                `   Month: ${state.currentMonth}\n` +
                `\n` +
                `   This phase declares a dependency on '${depId}' but that phase has not\n` +
                `   executed yet this step. Check phase order numbers or remove the dependency.\n` +
                `\n` +
                `   Executed phases so far: ${Array.from(ctx.executedPhases).join(', ')}`
              );
            }
          }
        }

        // PERFORMANCE INSTRUMENTATION (Oct 28, 2025)
        const startTime = this.enableTiming ? performance.now() : 0;

        const result = phase.execute(state, rng, ctx);

        // PERFORMANCE INSTRUMENTATION (Oct 28, 2025)
        if (this.enableTiming) {
          const elapsed = performance.now() - startTime;
          const existing = this.phaseTimings.get(phase.name) || { totalMs: 0, callCount: 0 };
          this.phaseTimings.set(phase.name, {
            totalMs: existing.totalMs + elapsed,
            callCount: existing.callCount + 1
          });
        }

        // Collect events
        if (result.events && result.events.length > 0) {
          allEvents.push(...result.events);
        }

        // Handle state replacement (some phases return new state)
        if (result.newState) {
          // Copy properties from new state to current state
          Object.assign(state, result.newState);
        }

        // Store metadata in context for later phases
        if (result.metadata) {
          ctx.data.set(phase.id, result.metadata);
        }

        // Mark this phase as executed (for dependency tracking)
        ctx.executedPhases.add(phase.id);

        // DEBUG (Oct 28, 2025): Check population integrity after each phase
        if (isNaN(state.humanPopulationSystem.population)) {
          console.error(`\n❌ Population became NaN after phase "${phase.name}" (${phase.id})`);
          console.error(`   Month: ${state.currentMonth}`);
          console.error(`   Phase order: ${phase.order}`);
          throw new Error(`Phase "${phase.name}" corrupted population to NaN`);
        }
      } catch (error) {
        console.error(`\n❌ FATAL ERROR in phase "${phase.name}" (${phase.id}):`, error);
        console.error(`   Month: ${state.currentMonth}`);
        console.error(`   This error will halt the simulation to prevent invalid state propagation.`);

        // FIX (Oct 26, 2025): Re-throw to fail loudly - defensive fallback was masking bugs
        // Previous behavior: silently continued, causing paradigm scores to stay at 50.0
        // New behavior: throw immediately so bugs can't hide
        throw error;
      }
    }

    return allEvents;
  }

  /**
   * Get execution order (for debugging/documentation)
   */
  getExecutionOrder(): string[] {
    if (!this.sorted) {
      this.sortPhases();
    }
    return this.phases.map(p => `[${p.order}] ${p.name} (${p.id})`);
  }

  /**
   * Get phase count
   */
  getPhaseCount(): number {
    return this.phases.length;
  }

  /**
   * Get phase by ID
   */
  getPhase(id: string): SimulationPhase | undefined {
    return this.phases.find(p => p.id === id);
  }

  /**
   * Clear all registered phases (useful for testing)
   */
  clear(): void {
    this.phases = [];
    this.sorted = false;
  }

  /**
   * Sort phases by order
   */
  private sortPhases(): void {
    this.phases.sort((a, b) => {
      // Primary sort: by order
      if (a.order !== b.order) {
        return a.order - b.order;
      }
      // Secondary sort: by name (for stability)
      return a.name.localeCompare(b.name);
    });
    this.sorted = true;
  }

  // PERFORMANCE INSTRUMENTATION (Oct 28, 2025)

  /**
   * Enable performance timing for all phases
   */
  enablePerformanceTiming(): void {
    this.enableTiming = true;
    this.phaseTimings.clear();
  }

  /**
   * Disable performance timing
   */
  disablePerformanceTiming(): void {
    this.enableTiming = false;
  }

  /**
   * Get phase timing statistics
   */
  getPhaseTimings(): Map<string, { totalMs: number; callCount: number }> {
    return new Map(this.phaseTimings);
  }

  /**
   * Print phase timing report to console
   */
  printPhaseTimings(): void {
    if (this.phaseTimings.size === 0) {
      console.log('\n⚠️  No timing data collected. Call enablePerformanceTiming() first.');
      return;
    }

    const sorted = Array.from(this.phaseTimings.entries())
      .map(([name, data]) => ({
        phaseName: name,
        totalMs: data.totalMs,
        callCount: data.callCount,
        avgMs: data.totalMs / data.callCount
      }))
      .sort((a, b) => b.totalMs - a.totalMs);

    console.log('\n📊 PHASE TIMING ANALYSIS');
    console.log('='.repeat(80));
    console.log('Phase Name'.padEnd(40) + 'Total (ms)'.padStart(12) + 'Calls'.padStart(8) + 'Avg (ms)'.padStart(12));
    console.log('-'.repeat(80));

    let totalTime = 0;
    for (const timing of sorted) {
      totalTime += timing.totalMs;
      console.log(
        timing.phaseName.padEnd(40) +
        timing.totalMs.toFixed(1).padStart(12) +
        timing.callCount.toString().padStart(8) +
        timing.avgMs.toFixed(2).padStart(12)
      );
    }

    console.log('-'.repeat(80));
    console.log('TOTAL'.padEnd(40) + totalTime.toFixed(1).padStart(12));
    console.log('='.repeat(80));

    // Top 5 slowest phases
    console.log('\n🔴 TOP 5 SLOWEST PHASES:');
    sorted.slice(0, 5).forEach((timing, i) => {
      const pct = (timing.totalMs / totalTime * 100).toFixed(1);
      console.log(`  ${i + 1}. ${timing.phaseName}: ${timing.totalMs.toFixed(1)}ms (${pct}%)`);
    });
  }

  /**
   * Reset phase timing statistics
   */
  resetPhaseTimings(): void {
    this.phaseTimings.clear();
  }
}
